INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(25001, 'John 3:8', 'John', 3, 8, '&nbsp;هوا اخوا ديخوا الوځى. تۀ د دې آواز خو اورې خو دا نۀ شې وئيلے چې دا د کومې راځى او چرته ځى. نو دغه حال د هر هغه چا دے چې د روحُ القُدس نه پېدا شوى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25002, 'John 3:9', 'John', 3, 9, '&nbsp;نيکوديموس ترې بيا تپوس وکړو، ”دا څنګه ممکنه ده؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25003, 'John 3:10', 'John', 3, 10, '&nbsp;عيسىٰ ورته وفرمائيل، ”تۀ د يهوديانو لوئ اُستاذ يې او د دې نه ناخبره يې؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25004, 'John 3:11', 'John', 3, 11, '&nbsp;زۀ درته رښتيا وايم چې مونږ هغه څۀ وايو چې څۀ راته معلوم دى او د هغې ګواهى ورکوو چې څۀ مو ليدلى دى، خو اوس هم تاسو زمونږ ګواهى نۀ منئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25005, 'John 3:12', 'John', 3, 12, '&nbsp;کۀ چرې تاسو زما عام خبرې نۀ منئ، نو کۀ زۀ درته آسمانى خبرې وکړم نو تاسو به يې څنګه ومنئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25006, 'John 3:13', 'John', 3, 13, '&nbsp;هيڅوک هم چرې آسمان ته نۀ دے ختلے بې د هغۀ نه څوک چې د آسمان نه راکوز شو، يعنې اِبن آدم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25007, 'John 3:14', 'John', 3, 14, '&nbsp;لکه څنګه چې موسىٰ په بيابان کښې مار په ستنې راځوړند کړے وو نو اِبن آدم به ضرور هم دغسې وخېژولے شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25008, 'John 3:15', 'John', 3, 15, '&nbsp;دې دپاره چې څوک په هغۀ ايمان ساتى نو هغه به د تل ژوندون ومومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25009, 'John 3:16', 'John', 3, 16, '&nbsp;خُدائ پاک د دې دُنيا سره داسې مينه وکړله چې خپل اېک يو زوئ يې هم ورکړو، نو څوک هم چې په هغۀ ايمان راوړى هلاک به نۀ شى خو د تل ژوندون به بيا مومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25010, 'John 3:17', 'John', 3, 17, '&nbsp;خُدائ پاک خپل زوئ دُنيا ته د دُنيا د مجرم کولو دپاره را ونۀ لېږلو بلکې د دې دپاره چې د هغۀ په وسيله دُنيا بچ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25011, 'John 3:18', 'John', 3, 18, '&nbsp;څوک چې په هغۀ ايمان راوړى نو هغه به مجرم نۀ شى خو چا چې پرې ايمان نۀ دے راوړے هغه خو د مخکښې نه مجرم شوے دے ځکه چې هغوئ د خُدائ پاک د اېک يو زوئ په نوم ايمان رانۀ وړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25012, 'John 3:19', 'John', 3, 19, '&nbsp;او د مجرم کېدلو سبب دا دے چې دُنيا ته نُور راغلو خو خلق د نُور په ځائ په تيارۀ کښې خوشحاله وُو ځکه چې د هغوئ کارونه بد وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25013, 'John 3:20', 'John', 3, 20, '&nbsp;هر څوک چې بد کار کوى نو د نُور نه نفرت کوى او نُور ته نۀ راځى د دې دپاره چې د هغوئ بدکارونه ښکاره نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25014, 'John 3:21', 'John', 3, 21, '&nbsp;خو څوک چې نېک کارونه کوى هغوئ رڼا ته راځى دپاره د دې چې دا ترې څرګند شى چې د هغوئ کارونه د خُدائ پاک په وسيله دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25015, 'John 3:22', 'John', 3, 22, '&nbsp;پس د دې نه عيسىٰ سره د مريدانو يهوديه ته لاړو او د هغوئ سره هلته د څۀ وخت دپاره ايسار شو او خلقو ته يې بپتسمه ورکوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25016, 'John 3:23', 'John', 3, 23, '&nbsp;يحيىٰ هم په عينون کښې بپتسمه ورکوله، کوم چې شاليم ته نزدې دے، ځکه چې په هغه ځائ کښې اوبۀ ډيرې وې، او خلق هغۀ له راتلل او بپتسمه يې اخستله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25017, 'John 3:24', 'John', 3, 24, '&nbsp;دا د يحيىٰ د قېد کېدو نه وړاندې وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25018, 'John 3:25', 'John', 3, 25, '&nbsp;د يحيىٰ د ځينې مريدانو د يو يهودى سره د پاکېدو د دستور په سر بحث وشو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25019, 'John 3:26', 'John', 3, 26, '&nbsp;نو هغوئ يحيىٰ له راغلل او ورته يې ووئيل، ”اُستاذه، تا سره چې د اُردن نه پورې غاړه کوم سړے وو د چا په حقله چې تا ګواهى کړې وه، هغه هم بپتسمه ورکوى، هر څوک ورته ورځى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25020, 'John 3:27', 'John', 3, 27, '&nbsp;يحيىٰ جواب ورکړو چې، ”انسان يو څيز هم تر هغې حاصلولے نۀ شى ترڅو چې هغۀ ته د آسمان نه مِلاو نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25021, 'John 3:28', 'John', 3, 28, '&nbsp;تاسو ته ښۀ پته ده چې ما وئيلى وُو چې زۀ مسيح نۀ يم، زۀ خو د هغۀ نه وړاندې رالېږلے شوے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25022, 'John 3:29', 'John', 3, 29, '&nbsp;ناوې د وادۀ د زلمى وى او د وادۀ د زلمى دوست څوک چې ورسره نزدې ولاړ وى نو هغه چې کله د هغۀ خبرې اورى، نو د زلمى په آواز اورېدو ډېر خوشحاليږى. نو دغه شان زما خوشحالى هم پوره کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25023, 'John 3:30', 'John', 3, 30, '&nbsp;هغه به ضرور لوئ او زۀ به ورکوټے شم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25024, 'John 3:31', 'John', 3, 31, '&nbsp;هغه څوک چې د بره نه راځى هغه د ټولو نه لوئ وى. او څوک چې د زمکې وى هغه د دُنيا سره تعلق ساتى او خبرې هم دُنياوى کوى. څوک چې د آسمان نه راځى هغه په ټولو اوچت وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25025, 'John 3:32', 'John', 3, 32, '&nbsp;هغۀ چې څۀ ليدلى او اورېدلى دى د هغې ګواهى کوى، خو هيڅوک هم د هغۀ ګواهى نۀ منى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25026, 'John 3:33', 'John', 3, 33, '&nbsp;چا چې د هغۀ ګواهى ومنله نو هغۀ د دې خبرې اِقرار وکړو چې خُدائ پاک رښتينے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25027, 'John 3:34', 'John', 3, 34, '&nbsp;ځکه څوک چې خُدائ پاک رالېږلے وى هغه د خُدائ کلام بيانوى، ځکه چې خُدائ پاک روحُ القُدس بې‌اندازې ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25028, 'John 3:35', 'John', 3, 35, '&nbsp;پلار د زوئ سره مينه کوى او هغۀ ته يې ټول اختيار ورکړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25029, 'John 3:36', 'John', 3, 36, '&nbsp;څوک چې په زوئ ايمان ساتى هغه به د تل ژوندون مالِک وى، خو څوک چې د زوئ نافرمانى وکړى هغه به دا ژوندون ونۀ ګورى او تل به د خُدائ پاک د غضب د لاندې وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25030, 'John 4:1', 'John', 4, 1, '&nbsp;عيسىٰ په دې خبر وو چې فريسيانو دا خبره واورېدله چې هغه د يحيىٰ نه هم زيات مريدان جوړوى او بپتسمه ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25031, 'John 4:2', 'John', 4, 2, '&nbsp;خو په حقيقت کښې عيسىٰ په خپله نه بلکې مريدانو يې بپتسمه ورکوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25032, 'John 4:3', 'John', 4, 3, '&nbsp;نو عيسىٰ يهوديه پرېښودله او يو ځل بيا ګليل ته لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25033, 'John 4:4', 'John', 4, 4, '&nbsp;خو هغۀ ته د سامريه نه تېرېدل ضرور وُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25034, 'John 4:5', 'John', 4, 5, '&nbsp;نو هغه د سامريې سوخار نومې ښار ته راغلو کوم چې هغه پټى ته نزدې وو چې يعقوب خپل زوئ يوسف له ورکړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25035, 'John 4:6', 'John', 4, 6, '&nbsp;هلته کښې د يعقوب کوهے وو او عيسىٰ د خپل سفر نه ستړے شوے وو نو هغه کوهى سره کښېناستو، دا د غرمې وخت وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25036, 'John 4:7', 'John', 4, 7, '&nbsp;نو بيا يوه سامرى ښځه اوبو وړلو له راغله او عيسىٰ هغې ته وفرمائيل چې، ”ما له اوبۀ راکړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25037, 'John 4:8', 'John', 4, 8, '&nbsp;د هغۀ مريدان د خوراک سامان اخستو دپاره ښار ته تلى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25038, 'John 4:9', 'John', 4, 9, '&nbsp;سامرى ښځې ورته ووئيل چې، ”تۀ يو يهودى زما غوندې سامرى ښځې نه د څښلو اوبۀ څنګه غواړې؟“ هغې ځکه داسې ووئيل چې يهوديان د سامريانو سره څۀ نۀ شريکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25039, 'John 4:10', 'John', 4, 10, '&nbsp;عيسىٰ هغې ته جواب ورکړو چې، ”کۀ چرې تا ته د خُدائ پاک د نعمت پته وے، او بله دا چې څوک چې ستا نه د څښلو اوبۀ غواړى دا څوک دے، نو تا به د هغۀ نه دا خواست کړے وو او هغۀ به تا له د ژوندون اوبۀ درکړې وې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25040, 'John 4:11', 'John', 4, 11, '&nbsp;ښځې هغۀ ته ووئيل چې، ”سړيه، تا سره خو بوقه هم نشته او دا کوهے ژور دے، نو تۀ به د کوم ځائ نه ما له د ژوندون اوبۀ راوړې؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25041, 'John 4:12', 'John', 4, 12, '&nbsp;ولې تۀ زمونږ د نيکۀ يعقوب نه لوئ سړے يې څۀ، چا چې مونږ له دا کوهے راکړو او په خپله يې د زامنو او څاروو سره د دې نه اوبۀ وڅښلې؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25042, 'John 4:13', 'John', 4, 13, '&nbsp;عيسىٰ هغې ته وفرمائيل، ”هر هغه څوک چې دا اوبۀ وڅښى هغه به بيا هم تږے کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25043, 'John 4:14', 'John', 4, 14, '&nbsp;خو چې څوک هغه اوبۀ وڅښى چې زۀ يې ورکوم هغه به هيڅکله نۀ تږے کيږى. زۀ چې کومې اوبۀ ورکوم هغه به په هغوئ کښې دننه لکه يوه چينه وګرځى چې همېشه به بهيږى او چې د تل ژوندون ورکوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25044, 'John 4:15', 'John', 4, 15, '&nbsp;ښځې ورته ووئيل، ”سړيه، هغه اوبۀ ما له راکړه نو چې زۀ بيا کله هم تږې نۀ شم او چې بيا اوبو راويستلو له دلته نۀ راځم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25045, 'John 4:16', 'John', 4, 16, '&nbsp;عيسىٰ ورته وفرمائيل، ”لاړه شه، خپل خاوند راوبله او بيا راشه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25046, 'John 4:17', 'John', 4, 17, '&nbsp;هغې جواب ورکړو چې، ”زما خاوند نشته.“ عيسىٰ هغې ته وفرمائيل، ”تۀ دا رښتيا وائې چې ستا خاوند نشته،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25047, 'John 4:18', 'John', 4, 18, '&nbsp;خو حقيقت دا دے چې تا پينځۀ مړونه کړى دى او اوس چې څوک تا سره دے ستا خاوند نۀ دے. تا چې څۀ ووئيل هغه رښتيا دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25048, 'John 4:19', 'John', 4, 19, '&nbsp;ښځې هغۀ تۀ ووئيل، ”مالِکه، ما ته ښکارى چې تۀ نبى يې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25049, 'John 4:20', 'John', 4, 20, '&nbsp;زمونږ نيکونو په دې غرۀ عبادت کولو خو تاسو يهوديان وايئ چې په کوم ځائ کښې مونږ ته د خُدائ پاک عبادت کول په کار دى هغه په يروشلم کښې دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25050, 'John 4:21', 'John', 4, 21, '&nbsp;عيسىٰ هغې ته وفرمائيل، ”خورې، باور وکړه چې يو وخت داسې راروان دے چې نۀ خو به تاسو د پلار عبادت په دې غر او نۀ په يروشلم کښې وکړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25051, 'John 4:22', 'John', 4, 22, '&nbsp;تاسو سامريان د هغۀ عبادت کوئ چې تاسو يې نۀ پېژنئ، خو مونږ د هغۀ عبادت کوُو چې مونږ يې پېژنو، ځکه چې خلاصون د يهوديانو د خوا نه دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25052, 'John 4:23', 'John', 4, 23, '&nbsp;خو وخت راروان دے بلکې اوس دے چې رښتينى عبادت کوونکى به پلار ته په روح او په رښتيا سره عبادت وکړى او پلار هم دغه شان عبادت کوونکى غواړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25053, 'John 4:24', 'John', 4, 24, '&nbsp;خُدائ پاک روح دے او هر څوک چې د هغۀ عبادت کوى نو هغه دې هم په روح او په رښتيا د هغۀ عبادت کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25054, 'John 4:25', 'John', 4, 25, '&nbsp;ښځې جواب ورکړو، ”زۀ پوهېږم چې مسح کړے شوے، يعنې مسيح راتلونکے دے. هر کله چې هغه راشى نو هغه به مونږ ته هر څۀ بيان کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25055, 'John 4:26', 'John', 4, 26, '&nbsp;عيسىٰ ورته وفرمائيل، ”هغه زۀ يم، زۀ چې تا سره خبرې کوم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25056, 'John 4:27', 'John', 4, 27, '&nbsp;په دغه وخت د هغۀ مريدان واپس راغلل او ډېر حېران شول چې هغه يې يوې ښځې سره په خبرو وکتلو خو په هغوئ کښې يو کس هم ونۀ وئيل چې، ”تۀ د دې نه څۀ غواړې،“ يا ”تۀ د دې سره خبرې ولې کوې؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25057, 'John 4:28', 'John', 4, 28, '&nbsp;نو ښځې بيا خپل منګے پرېښودو او ښار ته واپس په منډه لاړه او هلته يې خلقو ته ووئيل چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25058, 'John 4:29', 'John', 4, 29, '&nbsp;”راشئ، يو داسې سړے ووينئ چې ما څۀ کړى وُو هغه ټول يې راته ووئيل. کېدے شى چې دا مسيح وى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25059, 'John 4:30', 'John', 4, 30, '&nbsp;نو خلق د ښار نه راووتل او د عيسىٰ طرف ته روان شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25060, 'John 4:31', 'John', 4, 31, '&nbsp;په دې دوران کښې مريدانو په هغۀ زور ولګولو چې، ”اُستاذه، لږ څۀ وخوره.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25061, 'John 4:32', 'John', 4, 32, '&nbsp;خو هغۀ مريدانو ته وفرمائيل، ”ما سره داسې خوراک دے چې تاسو ته يې هيڅ پته نشته.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25062, 'John 4:33', 'John', 4, 33, '&nbsp;بيا مريدانو يو تر بله ووئيل چې، ”ولې چا هغۀ له خوراک راوړے دے څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25063, 'John 4:34', 'John', 4, 34, '&nbsp;عيسىٰ هغوئ ته وفرمائيل چې، ”زما خوراک څښاک دا دے چې زۀ د هغۀ رضا وکړم چا چې زۀ رالېږلے يم او چې د هغۀ کار پوره کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25064, 'John 4:35', 'John', 4, 35, '&nbsp;ولې تاسو دا نۀ وايئ چې څلور مياشتې نورې دى او بيا به لَو ګډ شى؟ خو زۀ تاسو ته دا وايم چې ګېرچاپېره پټو ته وګورئ چې د لَو کولو دپاره تيار دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25065, 'John 4:36', 'John', 4, 36, '&nbsp;اوس هم لَوګرى لګيا دى خپله مزدورى اخلى او د تل ژوندون دپاره مېوه راټولوى د دې دپاره چې کرونکى او لَوګرى دواړه په شريکه خوشحالى وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25066, 'John 4:37', 'John', 4, 37, '&nbsp;ځکه دا متل رښتيا دے چې يو يې کَرى او بل يې رېبى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25067, 'John 4:38', 'John', 4, 38, '&nbsp;ما تاسو ولېږلئ چې هغه فصل وريبئ په کوم چې تاسو څۀ کړاؤ نۀ دے کړے، نورو محنت وکړو او تاسو د هغوئ په محنت کښې شريک شوئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25068, 'John 4:39', 'John', 4, 39, '&nbsp;د هغه ښار ډېرو سامريانو په عيسىٰ ايمان راوړو د هغه ښځې د ګواهۍ په وجه چې، ”دۀ ما ته هغه هر څۀ ووئيل څۀ چې ما کله هم کړى وُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25069, 'John 4:40', 'John', 4, 40, '&nbsp;نو کله چې سامريان هغۀ له راغلل نو مِنت يې ورته وکړو چې مونږ سره پاتې شه، نو هغه هلته دوه ورځې ايسار شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25070, 'John 4:41', 'John', 4, 41, '&nbsp;او د هغۀ د کلام په وجه نورو ډېرو خلقو په هغۀ ايمان راوړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25071, 'John 4:42', 'John', 4, 42, '&nbsp;او هغوئ هغه ښځې ته ووئيل چې، ”مونږ صرف ستا د وينا په وجه په دۀ ايمان نۀ دے راوړے، ځکه چې مونږ اوس په خپله د هغۀ واورېدل او مونږ ته پته ولګېده چې دے په حقيقت کښې د دُنيا خلاصونکے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25072, 'John 4:43', 'John', 4, 43, '&nbsp;کله چې دوه ورځې تېرې شوې نو عيسىٰ د هغه ځائ نه ګليل ته روان شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25073, 'John 4:44', 'John', 4, 44, '&nbsp;نو عيسىٰ په خپله دا فرمائيلى وُو چې يو نبى هم په خپل ښار کښې عزتمند نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25074, 'John 4:45', 'John', 4, 45, '&nbsp;نو کله چې هغه ګليل ته راورسېدو نو ګليليانو د هغۀ هرکلے وکړو ځکه چې هغوئ په دغه وخت کښې د فسح اختر دپاره په يروشلم کښې موجود وو او د هغۀ ټول کارونه يې په خپله وليدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25075, 'John 4:46', 'John', 4, 46, '&nbsp;عيسىٰ يو ځل بيا د ګليل قانا نومې ځائ ته لاړو چرته چې هغۀ اوبۀ په ميو بدلې کړې وې. هلته يو سرکارى آفسر وو چې زوئ يې په کفرنحُوم کښې ناجوړه پروت وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25076, 'John 4:47', 'John', 4, 47, '&nbsp;کله چې هغۀ واورېدل چې عيسىٰ د يهوديه نه ښکته ګليل ته راغلے دے نو هغه ورله ورغلو او مِنت يې ورته وکړو چې، ”ما سره لاړ شه او زما زوئ جوړ کړه ځکه چې هغه مرګى حال پروت دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25077, 'John 4:48', 'John', 4, 48, '&nbsp;عيسىٰ هغۀ ته وفرمائيل چې، ”ترڅو چې تاسو خلق لوئ نښې ونۀ ګورئ نو تر هغې تاسو ايمان نۀ راوړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25078, 'John 4:49', 'John', 4, 49, '&nbsp;هغه آفسر ورته ووئيل چې، ”صاحبه، ما سره سمدستى لاړ شه زما زوئ مرګى حال دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25079, 'John 4:50', 'John', 4, 50, '&nbsp;عيسىٰ ورته وفرمائيل، ”کور ته لاړ شه، ستا زوئ به ژوندے پاتې شى.“ عيسىٰ چې څۀ وفرمائيل هغه سړى پرې يقين وکړو او کور ته روان شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25080, 'John 4:51', 'John', 4, 51, '&nbsp;هغه لا په لاره وو چې نوکرانو يې ورته خبر راوړو چې، ”زوئ خو دې په ښۀ کېدو او ژوندے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25081, 'John 4:52', 'John', 4, 52, '&nbsp;نو هغۀ تپوس ترېنه وکړو چې، ”څۀ وخت هغه په ښۀ کېدو شو؟“ هغوئ ورته ووئيل چې، ”پرون ماسپښين يوه بجه هغه تبې پرېښودلو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25082, 'John 4:53', 'John', 4, 53, '&nbsp;نو پلار يې پوهه شو چې دا هم هغه وخت وو چې عيسىٰ هغۀ ته فرمائيلى وُو چې، ”زوئ به دې ښۀ شى،“ نو هغۀ سره د ټول خاندانه پرې ايمان راوړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25083, 'John 4:54', 'John', 4, 54, '&nbsp;د يهوديه نه ګليل ته په راتلو دا د عيسىٰ دوېمه معجزه وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25084, 'John 5:1', 'John', 5, 1, '&nbsp;د دې نه پس د يهوديانو اختر وو، او عيسىٰ يروشلم ته لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25085, 'John 5:2', 'John', 5, 2, '&nbsp;په يروشلم کښې د ګډو د دروازې سره نزدې يو تالاب دے چې پينځۀ دالانونه په کښې ولاړ دى چې په آرامى ژبه کښې ورته بيت‌حسدا وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25086, 'John 5:3', 'John', 5, 3, '&nbsp;په دې دالانونو کښې ګڼ معذوران، ړاندۀ، ګوډ، شل، پراتۀ وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25087, 'John 5:4', 'John', 5, 4, '&nbsp;ځکه چې وخت په وخت به د خُدائ پاک يوه فرښته دې تالاب ته راکوزېدله او دا اوبۀ به يې خوځولې او هغه څوک چې به د ټولو نه وړومبے دې اوبو ته ورکوز شو نو هر څۀ بيمارى چې به يې وه د هغې نه به روغ شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25088, 'John 5:5', 'John', 5, 5, '&nbsp;په دغه خلقو کښې يو سړے وو چې د دوه کم څلوېښتو کالو راسې شل وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25089, 'John 5:6', 'John', 5, 6, '&nbsp;کله چې عيسىٰ هغه هلته پروت وليدو او د دې نه خبر شو چې دے د ډيرې مودې راسې بيمار دے، نو هغۀ ورته وفرمائيل، ”تۀ غواړې چې روغ شى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25090, 'John 5:7', 'John', 5, 7, '&nbsp;بيمار سړى جواب ورکړو چې، ”صاحبه، زما هيڅوک نشته چې کله اوبۀ وخوځولے شى نو چې ما دې تالاب ته ورکوز کړى. او کله چې زۀ اوبو له وررسم نو بل زما نه مخکښې وردانګلى وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25091, 'John 5:8', 'John', 5, 8, '&nbsp;بيا عيسىٰ هغۀ ته وفرمائيل چې، ”پاڅه، خپله بستره دې واخله او ځه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25092, 'John 5:9', 'John', 5, 9, '&nbsp;سړے سمدستى جک جوړ شو، او خپله بستره يې واخستله او روان شو. دا د سبت ورځ وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25093, 'John 5:10', 'John', 5, 10, '&nbsp;نو يهوديانو هغه روغ کړے شوى سړى ته ووئيل، ”دا د سبت ورځ ده. په شريعت کښې د سبت په ورځ تا ته د خپلې بسترې د وړلو اجازت نشته.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25094, 'John 5:11', 'John', 5, 11, '&nbsp;خو هغۀ جواب ورکړو چې، ”کوم سړى چې زۀ روغ کړم هغۀ ما ته وفرمائيل چې خپله بستره واخله او ځه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25095, 'John 5:12', 'John', 5, 12, '&nbsp;هغوئ د هغۀ نه تپوس وکړو چې، ”هغه سړے څوک دے چې تا ته يې ووئيل چې خپله بستره واخله او ځه؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25096, 'John 5:13', 'John', 5, 13, '&nbsp;خو هغه روغ شوى سړى ته دا پته ونۀ لګېده چې هغه څوک وو ځکه چې هلته ډېره ګڼه وه او عيسىٰ په ګڼه کښې غېب شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25097, 'John 5:14', 'John', 5, 14, '&nbsp;د دې نه پس عيسىٰ هغه د خُدائ په کور کښې وليدو او ورته يې وفرمائيل، ”وګوره، تۀ ښۀ شوے يې. نوره ګناه مۀ کوه، چې د دې نه درته زيات تکليف پېښ نۀ شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25098, 'John 5:15', 'John', 5, 15, '&nbsp;هغه سړے په مخه لاړو او د يهوديانو مشرانو ته يې ووئيل چې، ”دا هغه عيسىٰ وو چې ما له يې شفا راکړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25099, 'John 5:16', 'John', 5, 16, '&nbsp;نو په دې وجه د يهوديانو مشرانو د عيسىٰ زورول شروع کړل ځکه چې هغۀ دا کارونه د سبت په ورځ کول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25100, 'John 5:17', 'John', 5, 17, '&nbsp;نو عيسىٰ هغوئ ته جواب ورکړو چې، ”زما پلار لا تر اوسه کار کوى او زۀ هم کار کوم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');